        /// <summary>Where a fighter's setting id lives (false: not known).</summary>
        public static bool Find(string fighter, int id, out int block, out int offset)
        {
            block = offset = 0;
            if (fighter == null) return false;
            Dictionary<int, (int, int)> map;
            lock (Parsed)
                if (!Parsed.TryGetValue(fighter, out map))
                {
                    map = new Dictionary<int, (int, int)>();
                    if (Raw.TryGetValue(fighter, out var s))
                        foreach (var part in s.Split(' '))
                        {
                            var f = part.Split(':');
                            map[int.Parse(f[0])] = (int.Parse(f[1]), int.Parse(f[2], System.Globalization.NumberStyles.HexNumber));
                        }
                    Parsed[fighter] = map;
                }
            if (!map.TryGetValue(id, out var at)) return false;
            block = at.Item1; offset = at.Item2;
            return true;
        }
